/**
 * LogoForge - Herramienta: Versiones sobre color
 * ------------------------------------------------------------------
 * Toma lo que haya seleccionado (un logo, o varios) y crea una mesa de
 * trabajo nueva por cada color de fondo indicado, con una copia del
 * logo centrada encima.
 *
 * No modifica los colores del logo: se limita a duplicarlo. Asi funciona
 * igual con logos multicolor y con varios logos a la vez.
 */

if (typeof CG === "undefined") { var CG = {}; }

(function (CG) {

    var NOMBRE_CAPA = "VERSIONES";

    CG.mesasColor = function (opcionesJSON) {
        try {
            var opt = eval("(" + opcionesJSON + ")");

            if (app.documents.length === 0) {
                return '{"ok":false,"error":"Abre un documento con el logo."}';
            }
            var doc = app.activeDocument;
            var sel = doc.selection;
            if (!sel || sel.length === 0) {
                return '{"ok":false,"error":"Selecciona el logo antes de generar las versiones."}';
            }

            var colores = opt.colores || [];
            if (!colores.length) {
                return '{"ok":false,"error":"Añade al menos un color de fondo."}';
            }
            if (colores.length > 100) {
                return '{"ok":false,"error":"Demasiados colores (máximo 100)."}';
            }

            var caja = CG.cajaDe(sel);
            if (!caja) return '{"ok":false,"error":"No se pudo leer la geometría de la selección."}';

            var anchoLogo = caja[2] - caja[0];
            var altoLogo  = caja[1] - caja[3];
            if (anchoLogo <= 0 || altoLogo <= 0) {
                return '{"ok":false,"error":"La selección no tiene dimensiones utilizables."}';
            }

            // --- Tamaño de cada mesa ---
            var mayor = Math.max(anchoLogo, altoLogo);
            var margen = mayor * opt.margen / 100;
            var anchoMesa, altoMesa;
            if (opt.cuadrada) {
                anchoMesa = altoMesa = mayor + margen * 2;
            } else {
                anchoMesa = anchoLogo + margen * 2;
                altoMesa  = altoLogo  + margen * 2;
            }

            var separacion = mayor * opt.separacion / 100;
            var porFila = Math.max(1, Math.round(opt.columnas));

            // --- Punto de partida: debajo de todo lo que ya existe ---
            var minX = null, minY = null;
            for (var a = 0; a < doc.artboards.length; a++) {
                var r = doc.artboards[a].artboardRect;
                if (minX === null || r[0] < minX) minX = r[0];
                if (minY === null || r[3] < minY) minY = r[3];
            }
            if (minX === null) { minX = 0; minY = 0; }

            var x0 = minX;
            var y0 = minY - separacion - altoMesa;     // primera fila, debajo de todo

            // --- Capa destino ---
            var capa;
            try {
                capa = doc.layers.getByName(NOMBRE_CAPA);
                capa.locked = false;
                capa.visible = true;
            } catch (e) {
                capa = doc.layers.add();
                capa.name = NOMBRE_CAPA;
            }

            var creadas = 0, fallos = [];

            for (var i = 0; i < colores.length; i++) {
                var hex = String(colores[i]);
                var rgb = CG.hexARgb(hex);
                if (!rgb) { fallos.push(hex); continue; }

                var fila = Math.floor(i / porFila);
                var col  = i % porFila;

                var left   = x0 + col * (anchoMesa + separacion);
                var top    = y0 - fila * (altoMesa + separacion);
                var right  = left + anchoMesa;
                var bottom = top - altoMesa;

                // Mesa de trabajo. El nombre viaja al exportar, asi que lleva el color.
                var nueva = doc.artboards.add([left, top, right, bottom]);
                nueva.name = (opt.prefijo || "Logo") + " " + hex.toUpperCase();

                var grupo = capa.groupItems.add();
                grupo.name = nueva.name;

                // Fondo
                var fondo = grupo.pathItems.rectangle(top, left, anchoMesa, altoMesa);
                fondo.stroked = false;
                fondo.filled = true;
                fondo.fillColor = CG.creaColor(doc, rgb[0], rgb[1], rgb[2]);
                fondo.name = "Fondo " + hex.toUpperCase();

                // Copia del logo, sin tocar sus colores
                var copias = [];
                for (var s = 0; s < sel.length; s++) {
                    try {
                        copias.push(sel[s].duplicate(grupo, ElementPlacement.PLACEATEND));
                    } catch (e2) { /* se ignora lo que no admita duplicado */ }
                }
                if (copias.length === 0) {
                    grupo.remove();
                    nueva.remove();
                    fallos.push(hex + " (no se pudo duplicar)");
                    continue;
                }

                // PLACEATEND deja las copias al FONDO de la pila (conservando su
                // orden relativo entre ellas), asi que el fondo tapaba el logo.
                // Se manda el rectangulo al fondo despues de duplicar.
                fondo.zOrder(ZOrderMethod.SENDTOBACK);

                // Centrado en la mesa
                var cajaCopia = CG.cajaDe(copias);
                var dx = (left + right) / 2 - (cajaCopia[0] + cajaCopia[2]) / 2;
                var dy = (top + bottom) / 2 - (cajaCopia[1] + cajaCopia[3]) / 2;
                for (var c = 0; c < copias.length; c++) copias[c].translate(dx, dy);

                creadas++;
            }

            if (creadas === 0) {
                return '{"ok":false,"error":"No se pudo crear ninguna versión.",' +
                       '"avisos":' + lista(fallos) + '}';
            }

            doc.selection = null;
            app.redraw();

            return '{"ok":true,' +
                   '"mesas":' + creadas + ',' +
                   '"ancho":' + anchoMesa.toFixed(1) + ',' +
                   '"alto":' + altoMesa.toFixed(1) + ',' +
                   '"avisos":' + lista(fallos.length ? ["Colores no válidos: " + fallos.join(", ")] : []) + '}';

        } catch (e) {
            return '{"ok":false,"error":"' +
                   CG.escapaJSON("Error interno: " + e + " (línea " + e.line + ")") + '"}';
        }
    };

    function lista(arr) {
        var out = [];
        for (var i = 0; i < arr.length; i++) out.push('"' + CG.escapaJSON(arr[i]) + '"');
        return "[" + out.join(",") + "]";
    }

})(CG);
